H('265.d.1.G',4,"Compared to traditional media, social media gives marketers:","More direct two-way contact with audiences",["Less data","Only one-way contact","No reach"],"Interaction.")
H('265.d.2.A',3,"A legal concept that affects social media posts is:","Copyright",["Gravity","Symmetry","Altitude"],"Legal issues.")
